uintptr_t Base(DWORD pid,const std::wstring& path){HANDLE h=INVALID_HANDLE_VALUE;DWORD error=0;for(unsigned attempt=0;attempt<20;++attempt){h=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE|TH32CS_SNAPMODULE32,pid);if(h!=INVALID_HANDLE_VALUE)break;error=GetLastError();if(error!=ERROR_BAD_LENGTH)break;Sleep(10);}if(h==INVALID_HANDLE_VALUE){std::cerr<<"module_snapshot_failed win32_error="<<error<<"\n";return 0;}MODULEENTRY32W m{};m.dwSize=sizeof(m);uintptr_t found=0;if(Module32FirstW(h,&m)){do{if(CompareStringOrdinal(m.szExePath,-1,path.c_str(),-1,TRUE)==CSTR_EQUAL){found=reinterpret_cast<uintptr_t>(m.modBaseAddr);break;}}while(Module32NextW(h,&m));}else std::cerr<<"module_first_failed win32_error="<<GetLastError()<<"\n";CloseHandle(h);return found;}
